const bookings = $input.all().map(item => item.json);

const passengerStats = {};
const flightStats = {};

for (const booking of bookings) {
    const passengerId = booking.passenger_id;
    const flightId = booking.flight_id;

    // Passenger statistics
    if (!passengerStats[passengerId]) {
        passengerStats[passengerId] = {
            total_bookings: 0,
            cancelled_bookings: 0,
            booking_ids: []
        };
    }

    passengerStats[passengerId].total_bookings++;
    passengerStats[passengerId].booking_ids.push(booking.booking_id);

    if (booking.status === "cancelled") {
        passengerStats[passengerId].cancelled_bookings++;
    }

    // Flight statistics
    if (!flightStats[flightId]) {
        flightStats[flightId] = {
            total_bookings: 0,
            passenger_ids: []
        };
    }

    flightStats[flightId].total_bookings++;
    flightStats[flightId].passenger_ids.push(passengerId);
}

const suspicious = [];

// Pattern 1: many bookings by the same passenger
for (const [passengerId, stats] of Object.entries(passengerStats)) {
    if (stats.total_bookings >= 3) {
        suspicious.push({
            pattern: "HIGH_BOOKING_VOLUME",
            passenger_id: Number(passengerId),
            booking_count: stats.total_bookings,
            booking_ids: stats.booking_ids,
            reason: "Passenger has 3 or more historical bookings"
        });
    }

    // Pattern 2: repeated cancellations
    if (stats.cancelled_bookings >= 2) {
        suspicious.push({
            pattern: "REPEATED_CANCELLATIONS",
            passenger_id: Number(passengerId),
            cancelled_count: stats.cancelled_bookings,
            reason: "Passenger has 2 or more cancelled bookings"
        });
    }
}

// Pattern 3: many bookings on one flight
for (const [flightId, stats] of Object.entries(flightStats)) {
    if (stats.total_bookings >= 4) {
        suspicious.push({
            pattern: "HIGH_FLIGHT_BOOKING_VOLUME",
            flight_id: Number(flightId),
            booking_count: stats.total_bookings,
            passenger_ids: stats.passenger_ids,
            reason: "Flight has 4 or more historical bookings in the review set"
        });
    }
}

return [
    {
        json: {
            review_type: "historical_batch_fraud_review",
            bookings_scanned: bookings.length,
            suspicious_patterns_found: suspicious.length,
            suspicious_patterns: suspicious,
            reviewed_at: new Date().toISOString()
        }
    }
];
